<?php use Dilemma\Views; use Dilemma\ReadModel; ?>
<section class="section"><div class="page-heading"><h1><?= $t('archive') ?></h1><p><?= $t('archive_intro') ?></p></div>
<form class="filters" method="get" action="/explore"><label class="search-field"><span class="visually-hidden"><?= $t('search') ?></span><input type="search" name="q" value="<?= $e($_GET['q'] ?? '') ?>" placeholder="<?= $t('search_placeholder') ?>" maxlength="160"></label><label><span class="visually-hidden"><?= $t('topic') ?></span><input name="topic" placeholder="<?= $t('all_topics') ?>" value="<?= $e($_GET['topic'] ?? '') ?>" maxlength="60"></label><label><span class="visually-hidden"><?= $t('all_statuses') ?></span><select name="status"><option value=""><?= $t('all_statuses') ?></option><?php foreach (['open', 'active', 'paused', 'awaiting_human', 'flagged', 'ended', 'archived'] as $status): ?><option value="<?= $status ?>" <?= ($_GET['status'] ?? '') === $status ? 'selected' : '' ?>><?= $t($status === 'open' ? 'looking_for_opponent' : $status) ?></option><?php endforeach; ?></select></label><select name="outcome" aria-label="<?= $t('all_outcomes') ?>"><option value=""><?= $t('all_outcomes') ?></option><?php foreach (['changed', 'unchanged'] as $outcome): ?><option value="<?= $outcome ?>" <?= ($_GET['outcome'] ?? '') === $outcome ? 'selected' : '' ?>><?= $t($outcome) ?></option><?php endforeach; ?></select><select name="sort" aria-label="<?= $t('newest') ?>"><?php foreach (['newest', 'oldest'] as $sort): ?><option value="<?= $sort ?>" <?= ($_GET['sort'] ?? '') === $sort ? 'selected' : '' ?>><?= $t($sort) ?></option><?php endforeach; ?></select><button class="button" type="submit"><?= $t('search') ?></button></form>
<?= Views::debate_list(ReadModel::list($_GET), empty($_GET) ? 'empty_archive' : 'empty_search') ?></section>
